INSERT INTO `poi_themes` (`id`, `code`, `name`, `description`, `icon`, `cover_url`, `group_name`, `sort_order`, `enabled`) VALUES
('18', 'famous_buildings', '华夏建筑', '从古塔宫殿到现代地标，纵览中华建筑的千年风华', '🏯', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/themes/famous_buildings.jpg', '人文景观', '10', '1');
INSERT INTO `pois` (`id`, `name`, `category`, `lng`, `lat`, `adcode`, `address`, `summary`, `cover_url`, `hint_text`, `difficulty`, `source`, `used_count`, `verify_status`, `shape_type`, `radius_km`, `area_review`) VALUES
('5101', '故宫太和殿', 'famous_buildings', '116.397', '39.917', '110101', '北京市东城区东华门街道故宫博物院', '太和殿俗称金銮殿，是明清两代举行登极、大婚等重大典礼的场所，为中国现存最大的木结构殿宇。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5101.jpg', '紫禁城内最大的殿堂，俗称金銮殿', '1', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5102', '天坛祈年殿', 'famous_buildings', '116.407', '39.882', '110101', '北京市东城区天坛街道天坛公园', '祈年殿建于明永乐年间，三重檐圆形大殿，是明清皇帝祈谷丰年的场所，建筑造型为北京标志。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5102.jpg', '三重蓝瓦圆顶，皇帝祈谷之地', '1', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5103', '颐和园佛香阁', 'famous_buildings', '116.274', '39.999', '110108', '北京市海淀区青龙桥街道颐和园颐和园-佛香阁', '佛香阁位于万寿山前山，八面三层四重檐，是颐和园的标志性建筑，俯瞰昆明湖全貌。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5103.jpg', '万寿山上的八面三层楼阁', '1', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5104', '八达岭长城', 'famous_buildings', '116.024', '40.354', '110119', '北京市延庆区八达岭镇八达岭长城-北十二楼', '八达岭长城是明长城保存最完好的一段，城墙沿燕山山脊蜿蜒，为世界文化遗产万里长城的象征。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5104.jpg', '不到此处非好汉，明长城精华段', '1', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5105', '天安门城楼', 'famous_buildings', '116.397', '39.908', '110101', '北京市东城区东华门街道天安门前石狮子', '天安门城楼始建于明永乐年间，重檐歇山顶，是明清两代皇城正门，新中国开国大典宣告之地。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5105.jpg', '城楼悬挂国徽，开国大典所在地', '1', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5106', '正阳门', 'famous_buildings', '116.397', '39.899', '110101', '北京市东城区前门街道前门大街月亮湾公园', '正阳门俗称前门，是明清北京内城正南门，城楼与箭楼保存完好，为北京最高大的城门建筑。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5106.jpg', '前门楼子，内城正南门', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5107', '钟鼓楼', 'famous_buildings', '116.391', '39.941', '110102', '北京市西城区什刹海街道什刹海书院', '北京钟鼓楼位于中轴线北端，曾是元明清三代报时中心，鼓楼置鼓、钟楼悬铜钟，气势恢宏。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5107.jpg', '中轴线北端的报时建筑', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5108', '国家大剧院', 'famous_buildings', '116.389', '39.905', '110102', '北京市西城区西长安街街道国家大剧院', '国家大剧院由法国建筑师安德鲁设计，半椭圆钛金属穹顶浮于人工湖上，被誉为水上蛋壳。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5108.jpg', '天安门西侧的水上巨蛋', '1', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5109', '鸟巢国家体育场', 'famous_buildings', '116.397', '39.993', '110105', '北京市朝阳区奥运村街道国家体育场鸟巢文化中心', '鸟巢为2008年北京奥运会主体育场，钢铁网格编织结构宛如鸟巢，是奥运开闭幕式举办地。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5109.jpg', '2008奥运主场，钢铁编织巢穴', '1', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5110', '水立方', 'famous_buildings', '116.39', '39.993', '110105', '北京市朝阳区奥运村街道国家游泳中心', '水立方为2008年奥运会游泳馆，ETFE膜气枕结构模拟水泡形态，夜间通体蓝光，国家游泳中心。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5110.jpg', '方形的蓝色泡泡游泳馆', '1', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5111', 'CCTV总部大楼', 'famous_buildings', '116.461', '39.915', '110105', '北京市朝阳区呼家楼街道建国教育电工焊工富尔大厦', '央视总部大楼由OMA设计，两座塔楼斜向连接成环，外形被戏称为大裤衩，为北京CBD地标。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5111.jpg', '斜塔连接成环，被戏称大裤衩', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5112', '北海白塔', 'famous_buildings', '116.39', '39.925', '110102', '北京市西城区什刹海街道北海公园北海公园-琼华岛', '北海白塔建于清顺治年间，藏式覆钵塔立于琼华岛顶，为北海公园标志，倒映湖中。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5112.jpg', '琼华岛上的藏式白塔', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5113', '雍和宫', 'famous_buildings', '116.411', '39.948', '110101', '北京市东城区安定门街道后肖家胡同官书院小区(永康胡同)', '雍和宫原为清雍正帝潜邸，后改为藏传佛教寺院，殿宇辉煌，万福阁内白檀木大佛高十八米。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5113.jpg', '雍正帝潜邸改建的藏传寺院', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5114', '国子监辟雍', 'famous_buildings', '116.411', '39.949', '110101', '北京市东城区安定门街道安定门东大街北二环城市公园', '辟雍为国子监正殿，建于清乾隆年间，四周环水呈方形，为皇帝讲学之所，建筑规制独特。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5114.jpg', '国子监环水讲学殿宇', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5115', '恭王府', 'famous_buildings', '116.385', '39.939', '110102', '北京市西城区什刹海街道西煤厂胡同柳荫街社区居民委员会', '恭王府为清代规模最大的王府，原为和珅宅邸，府内福字碑与西洋门著称，花园精巧。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5115.jpg', '和珅旧宅，藏有福字碑', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5116', '明长陵祾恩殿', 'famous_buildings', '116.22', '40.258', '110114', '北京市昌平区十三陵镇天昱大樱桃采摘园明十三陵景区', '长陵为明成祖朱棣陵寝，祾恩殿是国内现存最大的楠木殿，六十根金丝楠木柱气势磅礴。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5116.jpg', '明十三陵中最大的楠木殿', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5117', '圆明园大水法', 'famous_buildings', '116.297', '40.008', '110108', '北京市海淀区青龙桥街道城关圆明园遗址公园', '大水法为圆明园西洋楼喷泉遗存，汉白玉雕石柱林立，见证1860年英法联军劫掠之劫难。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5117.jpg', '圆明园西洋喷泉残柱', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5118', '卢沟桥', 'famous_buildings', '116.211', '39.852', '110106', '北京市丰台区宛平街道射击场路', '卢沟桥建于金代，十一孔石拱桥横跨永定河，桥栏石狮姿态各异，1937年七七事变爆发地。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5118.jpg', '桥上石狮数不清，抗战爆发地', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5119', '景山万春亭', 'famous_buildings', '116.395', '39.926', '110102', '北京市西城区什刹海街道景山公园', '万春亭位于景山最高峰，三重檐黄瓦方亭，为北京旧城中轴线制高点，俯瞰故宫全景。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5119.jpg', '景山顶上俯瞰紫禁城', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5120', '太庙享殿', 'famous_buildings', '116.402', '39.916', '110101', '北京市东城区东华门街道故宫博物院', '太庙享殿为明清皇帝祭祖正殿，面阔十一间，黄琉璃瓦重檐庑殿顶，规制高于太和殿。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5120.jpg', '劳动人民文化宫内的祭祖殿', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5121', '法源寺', 'famous_buildings', '116.374', '39.893', '110102', '北京市西城区广安门内街道宣武门外大街北京市宣武青少年科学技术馆', '法源寺建于唐贞观年间，为北京最古刹，寺内古丁香著称，悯忠台与毗卢殿保留辽代遗构。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5121.jpg', '北京最古老的佛寺，藏丁香', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5122', '大钟寺钟楼', 'famous_buildings', '116.348', '39.964', '110108', '北京市海淀区北太平庄街道明光路中国农业科学院附属小学幼儿园', '大钟寺原名觉生寺，钟楼内悬永乐大钟，重四十六吨，钟身铸满经文，为明代铸钟巅峰。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5122.jpg', '寺内悬永乐大钟，重达四十六吨', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5123', '白云观', 'famous_buildings', '116.354', '39.918', '110102', '北京市西城区月坛街道月坛大厦(A座)月坛大厦A座', '白云观为道教全真派祖庭，始建于唐，元代邱处机曾驻锡，为北京最大的道观建筑群。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5123.jpg', '全真道祖庭，邱处机驻锡地', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5124', '先农坛', 'famous_buildings', '116.4', '39.876', '110101', '北京市东城区天坛街道永定门内大街永定门公园东城园区', '先农坛为明清皇帝祭祀先农神与躬耕之所，观耕台与具服殿保存完好，为古代农业祭祀建筑。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5124.jpg', '皇帝亲耕籍田的祭坛', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5125', '什刹海银锭桥', 'famous_buildings', '116.385', '39.939', '110102', '北京市西城区什刹海街道西煤厂胡同柳荫街社区居民委员会', '银锭桥位于前海与后海交汇处，单孔石拱桥小巧，为燕京小八景之一，观西山晚霞最佳处。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5125.jpg', '前海后海交界的小石拱桥', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5126', '永定门城楼', 'famous_buildings', '116.404', '39.864', '110101', '北京市东城区永定门外街道沙子口路43号天天家园', '永定门为北京中轴线南起点，明清北京外城正门，城楼于2004年复建，为中轴线申遗节点。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5126.jpg', '中轴线最南端的复建城楼', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5127', '东方明珠塔', 'famous_buildings', '121.499', '31.24', '310115', '上海市浦东新区陆家嘴街道《更上·海》环动多媒体秀东方明珠广播电视塔', '东方明珠塔高468米，十一球串联造型，为上海陆家嘴地标，亚洲第三高电视塔。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5127.jpg', '十一个球串成的浦东地标高塔', '1', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5128', '上海中心大厦', 'famous_buildings', '121.5', '31.233', '310115', '上海市浦东新区陆家嘴街道东岸绿道滨江公园', '上海中心大厦高632米，螺旋上升造型，为中国第一高楼，118层观光厅俯瞰浦江两岸。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5128.jpg', '中国第一高楼，螺旋上升造型', '1', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5129', '金茂大厦', 'famous_buildings', '121.5', '31.235', '310115', '上海市浦东新区陆家嘴街道未来资产大厦', '金茂大厦高420米，SOM设计，塔身取密檐塔意象，88层观光厅曾为大陆最高观光层。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5129.jpg', '塔身似密檐塔的陆家嘴高楼', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5130', '环球金融中心', 'famous_buildings', '121.5', '31.234', '310115', '上海市浦东新区陆家嘴街道花旗集团大厦', '环球金融中心高492米，顶部倒梯形风洞造型，被戏称为开瓶器，为上海第二高楼。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5130.jpg', '顶部开洞被戏称开瓶器', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5131', '外滩汇丰大楼', 'famous_buildings', '121.49', '31.239', '310101', '上海市黄浦区外滩街道中山东一路万国建筑博览群', '汇丰大楼建于1923年，新古典主义风格，穹顶马赛克壁画精美，曾号称从苏伊士到远东第一楼。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5131.jpg', '外滩穹顶马赛克壁画大楼', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5132', '外滩海关大楼', 'famous_buildings', '121.49', '31.239', '310101', '上海市黄浦区外滩街道中山东一路万国建筑博览群', '海关大楼建于1927年，希腊神庙式立面，大钟为亚洲第一大钟，钟声曾是外滩标志。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5132.jpg', '外滩大钟，亚洲第一钟', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5133', '和平饭店', 'famous_buildings', '121.49', '31.239', '310101', '上海市黄浦区外滩街道中山东一路万国建筑博览群', '和平饭店北楼原为沙逊大厦，哥特式屋顶绿色铜瓦，为外滩地标，老上海十里洋场象征。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5133.jpg', '外滩绿色尖顶的老饭店', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5134', '豫园', 'famous_buildings', '121.493', '31.227', '310101', '上海市黄浦区豫园街道洞天福地上海豫园', '豫园建于明嘉靖年间，江南古典园林，玉玲珑太湖石与点春堂著称，为上海四大名园之首。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5134.jpg', '老城厢明代园林，藏玉玲珑', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5135', '城隍庙', 'famous_buildings', '121.493', '31.227', '310101', '上海市黄浦区豫园街道洞天福地上海豫园', '上海城隍庙始建于明永乐年间，供奉秦裕伯，庙会商肆云集，为老上海民俗文化中心。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5135.jpg', '老城厢道教庙会商街', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5136', '中共一大会址', 'famous_buildings', '121.476', '31.232', '310101', '上海市黄浦区南京东路街道西藏中路上海城市规划展示馆', '中共一大会址位于石库门建筑内，1921年7月中共一大在此召开，为红色革命纪念地。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5136.jpg', '石库门里的红色会议旧址', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5137', '上海博物馆', 'famous_buildings', '121.476', '31.23', '310101', '上海市黄浦区南京东路街道上海人民广场', '上海博物馆位于人民广场，造型取天圆地方之意，馆藏青铜陶瓷书画逾百万件。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5137.jpg', '天圆地方造型的青铜器大馆', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
